class Solution {
public:
    long long minimumMaxValue(int n, int index, int value) {
        if (value == 1) return -1;
        long long p = smallestPrimeFactor(value);
        long long idx = index;
        long long nn = n;
        if (idx > 0 && (long long)value - p < 2LL * idx) return -1;
        long long t = nn - idx - 1;
        if (t == 0) return value;
        return (long long)value + p + 2LL * (t - 1);
    }
private:
    long long smallestPrimeFactor(int x) {
        if (x % 2 == 0) return 2;
        for (int i = 3; 1LL * i * i <= x; i += 2) {
            if (x % i == 0) return i;
        }
        return x;               // x is prime
    }
};
